/* ===== Budgtree reliability and virtual companion upgrade ===== */
(function(){
 const byId=id=>document.getElementById(id);
 const parseMoney=value=>Number(String(value??"").replace(/,/g,"").replace(/[^\d.-]/g,""))||0;
 const formatMoneyInput=value=>{
   let s=String(value??"").replace(/,/g,"").replace(/[^\d.]/g,"");
   if(!s)return "";
   const parts=s.split(".");
   parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,",");
   return parts[0]+(parts.length>1?"."+parts.slice(1).join("").slice(0,2):"");
 };
 const validEmail=value=>/^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)*\.[A-Z]{2,}$/i.test(String(value||"").trim());
 // Never silently assume an email domain. Accept standard domains with a real suffix.
 ["regEmail","loginEmail"].forEach(id=>{
   const el=byId(id); if(el){el.type="text";el.inputMode="email";el.autocomplete=id==="regEmail"?"email":"username"; }
 });
 ["regEmail","loginEmail"].forEach(id=>{
   const el=byId(id); if(el)el.closest("form")?.addEventListener("submit",e=>{if(!validEmail(el.value)){e.preventDefault();e.stopImmediatePropagation();const target=byId(id==="regEmail"?"registerError":"loginError");if(target)target.textContent="Enter a valid email address, including a complete domain such as @gmail.com, @yahoo.com, @outlook.com or your school domain.";el.focus();}},true);
 });
 // Convert monetary fields to text so thousands separators are valid while typing.
 const amountIds=["txAmount","goalTarget","goalInitial","depositAmount","allowanceInput","reminderAmount","otherPurchaseAmount","calendarEntryAmount"];
 amountIds.forEach(id=>{const el=byId(id);if(el){el.type="text";el.inputMode="decimal";el.autocomplete="off";}});
 function bindAmounts(root=document){
   root.querySelectorAll('input[inputmode="decimal"],input[data-budget]').forEach(el=>{
     if(el.dataset.ecoAmountBound)return;el.dataset.ecoAmountBound="1";
     el.addEventListener("input",()=>{const start=el.selectionStart;el.value=formatMoneyInput(el.value);try{el.setSelectionRange(el.value.length,el.value.length);}catch{}});
   });
 }
 bindAmounts();
 // Neutral starting values: all monetary inputs begin at zero, and remain editable.
 amountIds.forEach(id=>{const el=byId(id);if(el&&!el.value)el.value="0";});
 document.querySelectorAll("dialog").forEach(d=>d.addEventListener("toggle",()=>{if(d.open)d.querySelectorAll('input[inputmode="decimal"]').forEach(el=>{if(!el.value)el.value="0";});}));
 // Normalize comma formatted amounts before existing form handlers run.
 ["transactionForm","budgetForm","goalForm","depositForm","otherPurchaseForm","calendarEntryForm"].forEach(id=>{
   byId(id)?.addEventListener("submit",e=>{e.currentTarget.querySelectorAll('input[inputmode="decimal"],input[data-budget]').forEach(el=>{el.value=String(parseMoney(el.value));});},true);
 });
 ["saveAllowance","addReminder"].forEach(id=>byId(id)?.addEventListener("click",e=>{
   const root=e.currentTarget.closest(".panel")||document;
   root.querySelectorAll('input[inputmode="decimal"]').forEach(el=>el.value=String(parseMoney(el.value)));
 },true));
 const originalSetBudget=window.setBudgetInputs;
 if(typeof originalSetBudget==="function")window.setBudgetInputs=function(){originalSetBudget();byId("budgetInputs")?.querySelectorAll("[data-budget]").forEach(el=>{el.type="text";el.inputMode="decimal";el.value=formatMoneyInput(el.value);});bindAmounts(byId("budgetInputs")||document);};
 // Fix reports being initialized while hidden: redraw after the page is made visible.
 
 const oldRenderGoals=window.renderGoals;
 if(typeof oldRenderGoals==="function")window.renderGoals=function(){oldRenderGoals();const general=(data.transactions||[]).filter(t=>t.type==="savings").reduce((s,t)=>s+Number(t.amount||0),0);byId("savedTotal").textContent=money((data.goals||[]).reduce((s,g)=>s+Number(g.saved||0),0)+general);};
 const oldReports=window.renderReports;
 if(typeof oldReports==="function")window.renderReports=function(){
   oldReports();
   const wrap=document.querySelector("#cashflowChart")?.parentElement;
   if(wrap&&!window.Chart){
     const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;});
     let fb=wrap.querySelector(".cashflow-fallback");if(!fb){fb=document.createElement("div");fb.className="cashflow-fallback";wrap.appendChild(fb);}
     fb.innerHTML=months.map(m=>{const inc=data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="income").reduce((s,t)=>s+t.amount,0),exp=data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="expense").reduce((s,t)=>s+t.amount,0);return `<div class="fallback-month"><b>${new Date(m+"-01T00:00:00").toLocaleDateString("en-PH",{month:"short"})}</b><span>Income ${money(inc)}</span><span>Expenses ${money(exp)}</span></div>`;}).join("");
   }
 };
 
 const oldNavigate=window.navigate;
 if(typeof oldNavigate==="function")window.navigate=function(page){oldNavigate(page);if(page==="reports"){requestAnimationFrame(()=>{try{renderReports();}catch(err){console.error("Reports render:",err);}});}if(page==="dashboard"){requestAnimationFrame(()=>{try{renderDashboard();}catch(err){console.error("Dashboard render:",err);}});}if(page==="budget"){try{renderBudget();}catch(err){console.error("Budget render:",err);}}};

 document.addEventListener("click",e=>{
   const noteEdit=e.target.closest("[data-edit-note]");
   if(noteEdit){const list=data.calendarNotes[selectedDate]||[];const n=list.find(x=>x.id===noteEdit.dataset.editNote);if(n){const updated=prompt("Edit your reminder title:",n.title||n.text||"");if(updated!==null&&updated.trim()){n.title=updated.trim().slice(0,70);const desc=prompt("Edit reminder details:",n.description||"");if(desc!==null)n.description=desc.trim().slice(0,240);finishMutation("Calendar note updated.");}}}
   const noteToggle=e.target.closest("[data-toggle-note]");
   if(noteToggle){const list=data.calendarNotes[selectedDate]||[];const n=list.find(x=>x.id===noteToggle.dataset.toggleNote);if(n){n.done=!n.done;finishMutation(n.done?"Note completed.":"Note reopened.");}}
   if(e.target.closest("#saveCalendarNote")){
     const title=byId("calendarNoteTitle")?.value.trim(),desc=byId("calendarNoteInput")?.value.trim()||"";
     if(!title){toast("Enter a note title.","error");return;}
     data.calendarNotes[selectedDate]=data.calendarNotes[selectedDate]||[];
     data.calendarNotes[selectedDate].push({id:uid(),title,description:desc,type:byId("calendarNoteType")?.value||"Personal",priority:(byId("calendarNotePriority")?.value||"Low priority").replace(" priority",""),done:false});
     finishMutation("Date-specific note saved.");
   }
 },true);
 // Fix the profile ID preview and old compatibility code; keep all required elements available.
})();
